mkuse!{use crate :: sync :: atomic :: { Atomic , AtomicUsize , Ordering } ;}
mkitem!{mkstruct!{# [doc = " A type for TLS keys that are statically allocated."] # [doc = ""] # [doc = " This is basically a `LazyLock<Key>`, but avoids blocking and circular"] # [doc = " dependencies with the rest of `std`."] pub struct LazyKey { # [doc = " Inner static TLS key (internals)."] key : Atomic < usize > , # [doc = " Destructor for the TLS value."] dtor : Option < unsafe extern "C" fn (* mut u8) > , }}}
mkitem!{# [cfg (not (target_os = "nto"))] const KEY_SENTVAL : usize = 0 ;}
mkitem!{# [cfg (target_os = "nto")] const KEY_SENTVAL : usize = libc :: PTHREAD_KEYS_MAX + 1 ;}
mkitem!{mkimpl!{impl LazyKey { pub const fn new (dtor : Option < unsafe extern "C" fn (* mut u8) >) -> LazyKey { LazyKey { key : AtomicUsize :: new (KEY_SENTVAL) , dtor } } # [inline] pub fn force (& self) -> super :: Key { match self . key . load (Ordering :: Acquire) { KEY_SENTVAL => self . lazy_init () as super :: Key , n => n as super :: Key , } } fn lazy_init (& self) -> usize { let key1 = super :: create (self . dtor) ; let key = if key1 as usize != KEY_SENTVAL { key1 } else { let key2 = super :: create (self . dtor) ; unsafe { super :: destroy (key1) ; } key2 } ; rtassert ! (key as usize != KEY_SENTVAL) ; match self . key . compare_exchange (KEY_SENTVAL , key as usize , Ordering :: Release , Ordering :: Acquire ,) { Ok (_) => key as usize , Err (n) => unsafe { super :: destroy (key) ; n } , } } }}}